const a = await items.read("folder:159d84b7cec4a38c"); const b = await items.read("jira:SYN-45");
const st = await jira.listItems();
return {notes: a.gone?null:a.text, s45: b.gone?null:b.text, st: st.map(s=>s.gone?{id:s.id,gone:true}:{id:s.id,status:s.status.name,who:s.assignee?.name??null,pts:s.points})};

